css:
.moonfig {
  --ink: var(--figure-text, #1d2230);
  --mut: var(--figure-muted, #5d6475);
  --card: #f7f4ee;
  --line: #d9d2c3;
  --sun: #f2a516;
  --glow: rgba(242, 165, 22, .22);
  --lit: #f6e7bf;
  --dark: #39404f;
  --earth: #3f7fc2;
  --accent: #c2541f;
  --orbit: #9a927f;
  --shadow: rgba(30, 36, 52, .10);
  color: var(--ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  max-width: 980px; margin: 0 auto; display: grid; gap: 12px;
}
html[data-theme=dark] .moonfig {
  --card: #1b1f29; --line: #343a48; --dark: #262b36; --earth: #5d9be0;
  --orbit: #7f7a6d; --shadow: rgba(0, 0, 0, .35); --accent: #ff8a4c; --glow: rgba(242, 165, 22, .28);
}
.moonfig * { box-sizing: border-box; }
.mf-bar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.moonfig button {
  font: inherit; color: var(--ink); background: var(--card); border: 1px solid var(--line);
  border-radius: 999px; padding: 7px 14px; cursor: pointer; min-height: 36px;
}
.moonfig button:focus-visible, .moonfig input:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.moonfig button.primary { background: var(--accent); border-color: var(--accent); color: #fff; font-weight: 600; }
.status { margin-left: auto; font-size: 12px; color: var(--mut); padding: 3px 10px; border-radius: 999px; border: 1px dashed var(--line); }
.mf-grid { display: grid; grid-template-columns: 1.35fr 1fr; gap: 12px; }
@media (max-width: 680px) { .mf-grid { grid-template-columns: 1fr; } .status { margin-left: 0; } }
.panel { margin: 0; background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 10px; min-width: 0; }
.panel figcaption { font-size: 13px; color: var(--mut); margin-bottom: 6px; }
.panel figcaption b { display: inline-grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; background: var(--ink); color: var(--card); font-size: 11px; margin-right: 6px; }
.panel svg { display: block; width: 100%; height: auto; touch-action: none; }
#sky { max-width: 340px; margin: 0 auto; }
.key { list-style: none; padding: 0; margin: 6px 0 0; display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 12px; color: var(--mut); }
.key i { display: inline-block; width: 14px; height: 8px; margin-right: 5px; vertical-align: middle; border-radius: 2px; }
.k-lit { background: var(--lit); border: 1px solid var(--orbit); }
.k-face { border-top: 2px dashed var(--accent); height: 0 !important; }
.k-sight { border-top: 1.5px dotted var(--ink); height: 0 !important; }
.readout { text-align: center; margin-top: 8px; }
.readout p { margin: 2px 0; color: var(--mut); }
.readout .phase-name { font-size: 22px; font-weight: 700; color: var(--ink); letter-spacing: -.01em; }
.readout .big { font-size: 16px; font-weight: 600; color: var(--accent); }
.mf-pos { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 10px 12px; display: grid; gap: 6px; }
.mf-pos label { font-size: 13px; color: var(--mut); }
.mf-pos input[type=range] { width: 100%; accent-color: var(--accent); }
.num { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.num input { font: inherit; width: 5.5em; padding: 6px 8px; border-radius: 8px; border: 1px solid var(--line); background: transparent; color: var(--ink); }
.msg { margin: 0; min-height: 1.2em; font-size: 13px; color: var(--accent); }
.strip { display: grid; grid-template-columns: repeat(8, 1fr); gap: 6px; }
@media (max-width: 680px) { .strip { grid-template-columns: repeat(4, 1fr); } }
.moonfig .ph { border-radius: 10px; padding: 6px 2px; display: grid; justify-items: center; gap: 3px; font-size: 11.5px; line-height: 1.15; }
.moonfig .ph[aria-pressed=true] { border-color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); font-weight: 600; }
.mini svg { width: 30px; height: 30px; display: block; }
.mini-dark { fill: #2d3340; } .mini-lit { fill: var(--lit); } .mini-rim { fill: none; stroke: var(--orbit); stroke-width: .6; }
.simp { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 8px 12px; font-size: 13px; }
.simp summary { cursor: pointer; font-weight: 600; }
.simp ul { margin: 8px 0 2px; padding-left: 18px; color: var(--mut); }
/* SVG: top view */
.lbl { fill: var(--ink); font-size: 11px; }
.lbl.small { font-size: 10.5px; fill: var(--mut); }
.lbl.tiny { font-size: 9px; fill: var(--mut); }
.lbl.strong { font-weight: 700; font-size: 12px; }
.ray { stroke: var(--sun); stroke-width: .8; opacity: .45; }
.ray-head { fill: var(--sun); opacity: .55; }
.shadow { fill: var(--shadow); }
.sun { fill: var(--sun); }
.sun-glow { fill: var(--glow); }
.orbit { fill: none; stroke: var(--orbit); stroke-width: 1; stroke-dasharray: 2 3; }
.orbit-dir { fill: none; stroke: var(--orbit); stroke-width: 1.2; }
.orbit-head { fill: var(--orbit); }
.tick { fill: var(--orbit); }
.earth { fill: var(--earth); }
.night { fill: #0d1420; opacity: .55; }
.sight { stroke: var(--ink); stroke-width: 1; stroke-dasharray: 1.5 2.5; opacity: .7; }
.observer { fill: var(--accent); stroke: var(--card); stroke-width: 1; }
.moon-dark { fill: var(--dark); stroke: var(--orbit); stroke-width: .6; }
.moon-lit { fill: var(--lit); stroke: #b79f62; stroke-width: .6; }
.facing { fill: none; stroke: var(--accent); stroke-width: 2; stroke-dasharray: 3 2; stroke-linecap: round; }
.moon-hit { fill: transparent; cursor: grab; }
/* SVG: sky view (always night sky) */
.sky { fill: #101727; }
.star { fill: #dfe6f5; opacity: .8; }
.disk-dark { fill: #2a303d; }
.maria-dim ellipse { fill: #232835; }
.disk-lit { fill: #f4e6c2; }
.maria ellipse { fill: #d9c99f; opacity: .7; }
.disk-rim { fill: none; stroke: #4a5266; stroke-width: 1; }
.sky-lbl { fill: #b8c2d8; font-size: 12px; }
.sky-hint { fill: #f5c45a; font-size: 13px; font-weight: 600; }
@media (max-width: 680px) {
  .lbl.small { font-size: 12px; }
  .lbl.tiny { font-size: 10.5px; }
  .lbl.strong { font-size: 13.5px; }
}

