// Fases da Lua · modelo puro
// DESIGN: 2D editorial diagram (no mechanism). One state variable drives everything:
//   theta = elongação Sol–Terra–Lua em graus [0,360): 0 = Lua nova, 180 = Lua cheia.
// Top view in math coords (y = norte da eclíptica "para cima" no papel, órbita anti‑horária):
//   Sol muito distante na direção -x  ⇒ luz paralela viajando em +x.
//   Lua em Terra + r·(-cosθ, -sinθ).
// Fração iluminada vista da Terra: f = (1 - cos θ)/2  (sobreposição das metades
//   iluminada e voltada para a Terra). Disco no céu: limbo x=±s, terminador x=cosθ·s
//   com s = sqrt(R²-y²); crescente ilumina à direita (Hemisfério Norte).
// Simplificações: distâncias e tamanhos fora de escala; órbita circular e no plano
//   da eclíptica (real: elíptica, inclinada ~5,1°); Sol tratado como luz paralela.
export const SYNODIC_DAYS = 29.53;
export const ORBIT_R = 120;          // unidades do desenho (fora de escala)
export const RATE_DEG_S = 24;        // velocidade de reprodução (15 s por ciclo)
export const SUN_DIR = [-1, 0];      // direção da Terra para o Sol

export const PHASES = [
  { name: 'Lua nova', short: 'Nova', center: 0 },
  { name: 'Crescente', short: 'Crescente', center: 45 },
  { name: 'Quarto crescente', short: 'Q. crescente', center: 90 },
  { name: 'Gibosa crescente', short: 'Gib. cresc.', center: 135 },
  { name: 'Lua cheia', short: 'Cheia', center: 180 },
  { name: 'Gibosa minguante', short: 'Gib. ming.', center: 225 },
  { name: 'Quarto minguante', short: 'Q. minguante', center: 270 },
  { name: 'Minguante', short: 'Minguante', center: 315 },
];

export function norm(a) { const m = a % 360; return m < 0 ? m + 360 : m; }
const rad = (d) => d * Math.PI / 180;

export function illuminatedFraction(theta) { return (1 - Math.cos(rad(theta))) / 2; }
export function phaseIndex(theta) { return Math.floor(norm(theta + 22.5) / 45) % 8; }
export function phaseName(theta) { return PHASES[phaseIndex(theta)].name; }
export function ageDays(theta) { return norm(theta) / 360 * SYNODIC_DAYS; }
export function isWaxing(theta) { const t = norm(theta); return t > 0 && t < 180; }

// Top-view pose (math coords, Earth at origin)
export function topPose(theta) {
  const t = rad(theta);
  const moon = [-ORBIT_R * Math.cos(t), -ORBIT_R * Math.sin(t)];
  const d = Math.hypot(moon[0], moon[1]);
  const toEarth = [-moon[0] / d, -moon[1] / d];
  return { earth: [0, 0], moon, toEarth, litDir: SUN_DIR.slice(), dist: d };
}

// Fraction from geometry of the two hemispheres (independent of the formula above)
export function fractionFromPose(p) {
  const c = p.litDir[0] * p.toEarth[0] + p.litDir[1] * p.toEarth[1];
  return (1 + c) / 2;
}

// Lit interval of a horizontal chord at height y on a disk of radius R (sky view)
// hemi: 'N' | 'S' (south mirrors the disk: rotated 180°)
export function litInterval(theta, y, R, hemi = 'N') {
  const s = Math.sqrt(Math.max(0, R * R - y * y));
  const c = Math.cos(rad(theta));
  let iv = Math.sin(rad(theta)) >= 0 ? [c * s, s] : [-s, -c * s];
  if (hemi === 'S') iv = [-iv[1], -iv[0]];
  return iv;
}

// Closed lit polygon in disk-local coords (y down, SVG), n samples per edge
export function litPolygon(theta, R, hemi = 'N', n = 48) {
  const right = [], left = [];
  for (let i = 0; i <= n; i++) {
    const y = -R + 2 * R * i / n;
    const [a, b] = litInterval(theta, y, R, hemi);
    right.push([b, y]); left.push([a, y]);
  }
  return right.concat(left.reverse());
}

// Earth's umbra (coplanar simplification): moon centre within the shadow strip behind Earth
export function inEarthShadow(theta, earthR = 16) {
  const p = topPose(theta);
  return p.moon[0] > 0 && Math.abs(p.moon[1]) < earthR;
}

export function angleFromPoint(x, y) { return norm(Math.atan2(-y, -x) * 180 / Math.PI); }

export function createState() { return { theta: 60, playing: false, hemi: 'N', msg: '' }; }

export function reduce(s, a) {
  switch (a.type) {
    case 'toggle': return { ...s, playing: !s.playing, msg: '' };
    case 'pause': return { ...s, playing: false };
    case 'tick': return s.playing ? { ...s, theta: norm(s.theta + RATE_DEG_S * Math.max(0, Math.min(a.dt, 0.25))) } : s;
    case 'set': return { ...s, theta: norm(a.theta), msg: '' };
    case 'input': {
      const v = Number(String(a.value).replace(',', '.'));
      if (!Number.isFinite(v) || v < 0 || v >= 360 || String(a.value).trim() === '')
        return { ...s, msg: `Valor inválido: use 0–359°. Mantido ${Math.round(s.theta)}°.` };
      return { ...s, theta: v, msg: '' };
    }
    case 'drag': return { ...s, playing: false, theta: angleFromPoint(a.x, a.y), msg: '' };
    case 'phase': return { ...s, playing: false, theta: PHASES[a.i].center, msg: '' };
    case 'hemi': return { ...s, hemi: s.hemi === 'N' ? 'S' : 'N' };
    case 'reset': return createState();
    default: return s;
  }
}

export function readout(s) {
  const f = illuminatedFraction(s.theta);
  return {
    name: phaseName(s.theta),
    index: phaseIndex(s.theta),
    percent: Math.round(f * 100),
    age: ageDays(s.theta).toFixed(1).replace('.', ','),
    angle: Math.round(s.theta) % 360,
    trend: norm(s.theta) === 0 || norm(s.theta) === 180 ? '—' : isWaxing(s.theta) ? 'crescendo' : 'diminuindo',
  };
}

