import * as M from './model.mjs';

function diskAreaFraction(theta, hemi = 'N', R = 1, n = 400) {
  let lit = 0, tot = 0;
  for (let i = 0; i < n; i++) {
    const y = -R + (i + 0.5) * 2 * R / n;
    const s = Math.sqrt(R * R - y * y);
    const [a, b] = M.litInterval(theta, y, R, hemi);
    lit += Math.max(0, b - a); tot += 2 * s;
  }
  return lit / tot;
}

export function verify() {
  const out = [];
  const add = (name, passed, detail = '') => out.push({ name, passed: !!passed, detail });
  const samples = Array.from({ length: 361 }, (_, i) => i);

  // 1. painted disk area equals the model fraction through the whole cycle
  let worst = 0, at = 0;
  for (const t of samples) { const e = Math.abs(diskAreaFraction(t) - M.illuminatedFraction(t)); if (e > worst) { worst = e; at = t; } }
  add('Área iluminada do disco = fração do modelo (ciclo completo)', worst < 0.01, `erro máx ${worst.toFixed(4)} em ${at}°`);

  // 2. hemisphere-overlap geometry gives the same fraction (independent derivation)
  let w2 = 0;
  for (const t of samples) w2 = Math.max(w2, Math.abs(M.fractionFromPose(M.topPose(t)) - M.illuminatedFraction(t)));
  add('Sobreposição metade iluminada × metade voltada à Terra confere', w2 < 1e-9, `erro ${w2}`);

  // 3. limiting cases
  add('Nova 0%, quartos 50%, cheia 100%',
    M.illuminatedFraction(0) < 1e-9 && Math.abs(M.illuminatedFraction(90) - 0.5) < 1e-9 &&
    Math.abs(M.illuminatedFraction(270) - 0.5) < 1e-9 && M.illuminatedFraction(180) > 1 - 1e-9);

  // 4. illumination always toward the Sun, orbit radius constant
  let okLit = true, okR = true;
  for (const t of samples) { const p = M.topPose(t); if (p.litDir[0] !== -1 || p.litDir[1] !== 0) okLit = false; if (Math.abs(p.dist - M.ORBIT_R) > 1e-9) okR = false; }
  add('Lado iluminado sempre voltado ao Sol', okLit);
  add('Raio orbital constante (órbita circular simplificada)', okR);

  // 5. phase names advance in order without skips over one cycle
  const seq = [];
  for (let t = 0; t < 360; t += 0.5) { const i = M.phaseIndex(t); if (seq[seq.length - 1] !== i) seq.push(i); }
  add('Sequência de 8 nomes em ordem, sem saltos', seq.join(',') === '0,1,2,3,4,5,6,7,0', seq.join(','));

  // 6. waxing lit on right (N), mirrored in S; waning on left
  const cw = M.litInterval(60, 0, 1, 'N'), cs = M.litInterval(60, 0, 1, 'S'), wn = M.litInterval(300, 0, 1, 'N');
  add('Crescente iluminada à direita (N), à esquerda (S); minguante à esquerda (N)',
    cw[0] > 0 && cw[1] === 1 && cs[1] < 0 && cs[0] === -1 && wn[1] < 0);
  add('Hemisfério Sul não altera a fração', Math.abs(diskAreaFraction(130, 'S') - diskAreaFraction(130, 'N')) < 1e-9);

  // 7. phases are not caused by Earth's shadow
  const shadowAt = samples.filter((t) => M.inEarthShadow(t));
  const qOk = !M.inEarthShadow(90) && !M.inEarthShadow(270) && !M.inEarthShadow(45);
  add('Sombra da Terra só perto da cheia (fração máx.), nunca nos quartos/crescentes',
    qOk && shadowAt.every((t) => M.illuminatedFraction(t) > 0.98), `${shadowAt[0]}–${shadowAt[shadowAt.length - 1]}°`);

  // 8. transitions: play advances, pause stops, wraps
  let s = M.createState();
  const t0 = s.theta;
  s = M.reduce(s, { type: 'tick', dt: 0.1 });
  const pausedStill = s.theta === t0;
  s = M.reduce(s, { type: 'toggle' });
  s = M.reduce(s, { type: 'tick', dt: 0.1 });
  const moved = Math.abs(s.theta - t0 - M.RATE_DEG_S * 0.1) < 1e-9;
  s = M.reduce(s, { type: 'toggle' }); const th = s.theta;
  s = M.reduce(s, { type: 'tick', dt: 0.1 });
  add('Reproduzir avança, pausar congela', pausedStill && moved && s.theta === th);
  let w = M.reduce({ ...M.createState(), theta: 355, playing: true }, { type: 'tick', dt: 0.25 });
  add('Órbita volta a 0° após 360°', w.theta >= 0 && w.theta < 5, `${w.theta}`);

  // 9. drag round trip and invalid input
  let rt = 0;
  for (const t of [0, 33, 90, 181, 270, 359]) { const p = M.topPose(t); const d = M.reduce(M.createState(), { type: 'drag', x: p.moon[0], y: p.moon[1] }); rt = Math.max(rt, Math.abs(((d.theta - t + 540) % 360) - 180)); }
  add('Arrastar a Lua reproduz o ângulo', rt < 1e-6, `${rt}`);
  const bad = M.reduce({ ...M.createState(), theta: 90 }, { type: 'input', value: '400' });
  add('Ângulo fora de 0–359° é recusado', bad.theta === 90 && bad.msg.includes('inválido'));

  // 10. age monotonic within the cycle
  let mono = true;
  for (let t = 1; t < 360; t++) if (M.ageDays(t) <= M.ageDays(t - 1)) mono = false;
  add('Idade lunar cresce de 0 a 29,53 dias', mono && M.ageDays(359.99) < M.SYNODIC_DAYS);
  return out;
}

