import * as M from './model.mjs';
import * as G from './geometry.mjs';

export function mount(root, env = {}) {
  let s = M.createState();
  let raf = 0, last = null, visible = true, dragging = false;
  root.classList.add('moonfig');
  root.innerHTML = `
  <div class="mf-bar" role="group" aria-label="Controles">
    <button id="play" type="button" class="primary" aria-pressed="false">Reproduzir</button>
    <button id="reset" type="button">Reiniciar</button>
    <button id="hemi" type="button">Hemisfério: Norte</button>
    <span id="status" class="status" role="status" aria-live="polite">Pausado</span>
  </div>
  <div class="mf-grid">
    <figure class="panel">
      <figcaption><b>1</b> Vista de cima: Sol, Terra e Lua</figcaption>
      <svg id="top" viewBox="${G.TOP_VB.join(' ')}" role="img" aria-label="Vista superior da órbita; arraste a Lua">
        <g id="top-static">${G.topStatic()}</g><g id="top-dyn"></g>
      </svg>
      <ul class="key">
        <li><i class="k-lit"></i>metade iluminada — sempre voltada ao Sol</li>
        <li><i class="k-face"></i>metade voltada para a Terra</li>
        <li><i class="k-sight"></i>linha de visada do observador</li>
      </ul>
    </figure>
    <figure class="panel">
      <figcaption><b>2</b> O disco lunar visto da Terra</figcaption>
      <svg id="sky" viewBox="${G.SKY_VB.join(' ')}" role="img" aria-label="Disco lunar visto da Terra"></svg>
      <div class="readout">
        <p id="phase-name" class="phase-name"></p>
        <p id="fraction" class="big"></p>
        <p id="age"></p>
        <p id="angle-out"></p>
      </div>
    </figure>
  </div>
  <div class="mf-pos">
    <label for="angle">Posição na órbita (ângulo Sol–Terra–Lua)</label>
    <input id="angle" type="range" min="0" max="359" step="1">
    <div class="num">
      <label for="angle-num">Ângulo exato (°)</label>
      <input id="angle-num" type="text" inputmode="decimal" size="5">
      <button id="apply" type="button">Aplicar</button>
    </div>
    <p id="msg" class="msg" aria-live="polite"></p>
  </div>
  <div class="strip" role="group" aria-label="Comparar fases principais">
    ${M.PHASES.map((p, i) => `<button id="ph-${i}" type="button" class="ph" aria-pressed="false"><span class="mini"></span><span>${p.short}</span></button>`).join('')}
  </div>
  <details class="simp">
    <summary>Simplificações deste modelo</summary>
    <ul>
      <li><b>Fora de escala:</b> a Lua está ~30 diâmetros terrestres da Terra e o Sol ~400 vezes mais longe que a Lua; os tamanhos também estão exagerados.</li>
      <li><b>Órbita circular e plana:</b> a órbita real é levemente elíptica e inclinada ~5,1° em relação à eclíptica. Por isso a Lua cheia geralmente passa acima ou abaixo da sombra da Terra — eclipses são raros.</li>
      <li><b>Luz paralela:</b> o Sol é tratado como uma fonte muito distante; a metade iluminada aponta sempre para ele.</li>
      <li><b>Mês sinódico médio:</b> 29,53 dias de nova a nova; a idade mostrada é proporcional ao ângulo.</li>
      <li>A fase depende só do ângulo Sol–Terra–Lua: fração iluminada = (1 − cos θ) ÷ 2. A sombra da Terra não participa.</li>
    </ul>
  </details>`;

  const $ = (id) => root.querySelector('#' + id);
  const topSvg = $('top'), dyn = $('top-dyn'), sky = $('sky');
  const range = $('angle'), num = $('angle-num');
  const phBtns = M.PHASES.map((_, i) => $('ph-' + i));
  let lastHemi = null;

  function draw() {
    const r = M.readout(s);
    dyn.innerHTML = G.topDynamic(s);
    sky.innerHTML = G.skyView(s);
    $('phase-name').textContent = r.name;
    $('fraction').textContent = `Iluminada: ${r.percent}%`;
    $('age').textContent = `Idade: ${r.age} dias · ${r.trend}`;
    $('angle-out').textContent = `Ângulo Sol–Terra–Lua: ${r.angle}°`;
    range.value = String(r.angle);
    if (root.ownerDocument.activeElement !== num) num.value = String(r.angle);
    $('msg').textContent = s.msg;
    $('play').textContent = s.playing ? 'Pausar' : 'Reproduzir';
    $('play').setAttribute('aria-pressed', String(s.playing));
    $('hemi').textContent = `Hemisfério: ${s.hemi === 'N' ? 'Norte' : 'Sul'}`;
    $('status').textContent = s.playing ? 'Órbita em movimento' : 'Pausado';
    phBtns.forEach((b, i) => b.setAttribute('aria-pressed', String(i === r.index)));
    if (lastHemi !== s.hemi) {
      phBtns.forEach((b, i) => { b.querySelector('.mini').innerHTML = G.miniDisk(M.PHASES[i].center, s.hemi); });
      lastHemi = s.hemi;
    }
  }

  function frame(ts) {
    raf = 0;
    if (!s.playing || !visible) return;
    const dt = last == null ? 0 : (ts - last) / 1000;
    last = ts;
    s = M.reduce(s, { type: 'tick', dt });
    draw();
    raf = requestAnimationFrame(frame);
  }
  function startLoop() { if (!raf && s.playing && visible) { last = null; raf = requestAnimationFrame(frame); } }
  function stopLoop() { if (raf) cancelAnimationFrame(raf); raf = 0; last = null; }
  function act(a) { s = M.reduce(s, a); draw(); if (s.playing) startLoop(); else stopLoop(); }

  const on = (el, ev, fn) => { el.addEventListener(ev, fn); return () => el.removeEventListener(ev, fn); };
  const offs = [
    on($('play'), 'click', () => act({ type: 'toggle' })),
    on($('reset'), 'click', () => act({ type: 'reset' })),
    on($('hemi'), 'click', () => act({ type: 'hemi' })),
    on(range, 'input', () => act({ type: 'set', theta: Number(range.value) })),
    on($('apply'), 'click', () => act({ type: 'input', value: num.value })),
    on(num, 'keydown', (e) => { if (e.key === 'Enter') act({ type: 'input', value: num.value }); }),
    ...phBtns.map((b, i) => on(b, 'click', () => act({ type: 'phase', i }))),
  ];

  function svgPoint(e) {
    const m = topSvg.getScreenCTM();
    if (!m) return null;
    const p = new DOMPoint(e.clientX, e.clientY).matrixTransform(m.inverse());
    return G.toModel(p.x, p.y);
  }
  function nearOrbit(pt) { const d = Math.hypot(pt[0], pt[1]); return d > M.ORBIT_R - 30 && d < M.ORBIT_R + 30; }
  offs.push(
    on(topSvg, 'pointerdown', (e) => {
      const pt = svgPoint(e); if (!pt || !nearOrbit(pt)) return;
      dragging = true; topSvg.setPointerCapture?.(e.pointerId); e.preventDefault();
      act({ type: 'drag', x: pt[0], y: pt[1] });
    }),
    on(topSvg, 'pointermove', (e) => { if (!dragging) return; const pt = svgPoint(e); if (pt) act({ type: 'drag', x: pt[0], y: pt[1] }); }),
    on(topSvg, 'pointerup', () => { dragging = false; }),
    on(topSvg, 'pointercancel', () => { dragging = false; }),
    on(root, 'figure:environment', (e) => {
      const d = e.detail || {};
      if (typeof d.visible === 'boolean') { visible = d.visible; if (visible) startLoop(); else stopLoop(); }
    }),
  );

  draw();
  return () => { stopLoop(); offs.forEach((f) => f()); root.innerHTML = ''; };
}

