// Drawing helpers: pure SVG strings from model state. 2D editorial diagram.
import * as M from './model.mjs';

export const TOP_VB = [0, 0, 400, 326];
export const SKY_VB = [0, 0, 300, 300];
const EC = [244, 168];               // Earth centre on screen (top view)
const EARTH_R = 16, MOON_R = 13, SUN = [38, 168], SUN_R = 24;
const f1 = (n) => Math.round(n * 10) / 10;

export function toScreen([x, y]) { return [EC[0] + x, EC[1] - y]; }
export function toModel(sx, sy) { return [sx - EC[0], EC[1] - sy]; }

function polyPath(pts, cx, cy) {
  return 'M' + pts.map(([x, y]) => `${f1(cx + x)},${f1(cy + y)}`).join('L') + 'Z';
}

// Static layer of the top view (cached by figure)
export function topStatic() {
  let g = '';
  // parallel sunlight
  for (const y of [62, 104, 232, 274]) {
    g += `<line class="ray" x1="72" y1="${y}" x2="384" y2="${y}"/>`;
    g += `<path class="ray-head" d="M384,${y - 3.5}L391,${y}L384,${y + 3.5}Z"/>`;
  }
  g += `<text class="lbl small" x="76" y="56">luz solar ≈ paralela →</text>`;
  // Earth's shadow strip (coplanar simplification)
  g += `<rect class="shadow" x="${EC[0]}" y="${EC[1] - EARTH_R}" width="${392 - EC[0]}" height="${EARTH_R * 2}"/>`;
  g += `<text class="lbl tiny" x="389" y="${EC[1] + EARTH_R + 10}" text-anchor="end">sombra da Terra</text>`;
  // Sun
  g += `<circle class="sun-glow" cx="${SUN[0]}" cy="${SUN[1]}" r="${SUN_R + 10}"/>`;
  g += `<circle class="sun" cx="${SUN[0]}" cy="${SUN[1]}" r="${SUN_R}"/>`;
  g += `<text class="lbl strong" x="${SUN[0]}" y="${SUN[1] + SUN_R + 18}" text-anchor="middle">Sol</text>`;
  g += `<text class="lbl tiny" x="${SUN[0]}" y="${SUN[1] + SUN_R + 30}" text-anchor="middle">muito mais</text>`;
  g += `<text class="lbl tiny" x="${SUN[0]}" y="${SUN[1] + SUN_R + 40}" text-anchor="middle">longe</text>`;
  // orbit
  g += `<circle class="orbit" cx="${EC[0]}" cy="${EC[1]}" r="${M.ORBIT_R}"/>`;
  // direction arrow on orbit (counter‑clockwise seen from north)
  const a0 = 200 * Math.PI / 180, a1 = 225 * Math.PI / 180, R = M.ORBIT_R + 9;
  const p0 = toScreen([R * Math.cos(a0), R * Math.sin(a0)]), p1 = toScreen([R * Math.cos(a1), R * Math.sin(a1)]);
  g += `<path class="orbit-dir" d="M${f1(p0[0])},${f1(p0[1])}A${R},${R} 0 0 0 ${f1(p1[0])},${f1(p1[1])}"/>`;
  const tx = -Math.sin(a1), ty = Math.cos(a1); // CCW tangent in math coords
  const tip = toScreen([R * Math.cos(a1) + tx * 7, R * Math.sin(a1) + ty * 7]);
  const n1 = toScreen([R * Math.cos(a1) + 4 * Math.cos(a1), R * Math.sin(a1) + 4 * Math.sin(a1)]);
  const n2 = toScreen([R * Math.cos(a1) - 4 * Math.cos(a1), R * Math.sin(a1) - 4 * Math.sin(a1)]);
  g += `<path class="orbit-head" d="M${f1(tip[0])},${f1(tip[1])}L${f1(n1[0])},${f1(n1[1])}L${f1(n2[0])},${f1(n2[1])}Z"/>`;
  // eight principal positions
  M.PHASES.forEach((ph) => {
    const p = toScreen(M.topPose(ph.center).moon);
    g += `<circle class="tick" cx="${f1(p[0])}" cy="${f1(p[1])}" r="2.2"/>`;
  });
  const lab = (t, text, dx, dy, anchor) => {
    const p = toScreen(M.topPose(t).moon);
    g += `<text class="lbl small" x="${f1(p[0] + dx)}" y="${f1(p[1] + dy)}" text-anchor="${anchor}">${text}</text>`;
  };
  lab(0, 'Nova', -8, -14, 'end');
  lab(180, 'Cheia', 0, -16, 'middle');
  lab(90, 'Quarto crescente', 0, 26, 'middle');
  lab(270, 'Quarto minguante', 0, -18, 'middle');
  g += `<text class="lbl tiny" x="392" y="16" text-anchor="end">vista de cima do polo norte</text>`;
  g += `<text class="lbl tiny" x="392" y="28" text-anchor="end">fora de escala</text>`;
  return g;
}

// Dynamic layer: Earth day/night, Moon with lit and Earth-facing halves, sight line
export function topDynamic(s) {
  const p = M.topPose(s.theta);
  const [mx, my] = toScreen(p.moon);
  const [ex, ey] = EC;
  const dx = ex - mx, dy = ey - my, d = Math.hypot(dx, dy), ux = dx / d, uy = dy / d;
  let g = '';
  // Earth: night side away from Sun
  g += `<circle class="earth" cx="${ex}" cy="${ey}" r="${EARTH_R}"/>`;
  g += `<path class="night" d="M${ex},${ey - EARTH_R}A${EARTH_R},${EARTH_R} 0 0 1 ${ex},${ey + EARTH_R}Z"/>`;
  g += `<text class="lbl strong" x="${ex}" y="${ey + EARTH_R + 30}" text-anchor="middle">Terra</text>`;
  // sight line Earth → Moon and observer
  const ox = ex - ux * EARTH_R, oy = ey - uy * EARTH_R;
  g += `<line class="sight" x1="${f1(ox)}" y1="${f1(oy)}" x2="${f1(mx + ux * (MOON_R + 5))}" y2="${f1(my + uy * (MOON_R + 5))}"/>`;
  g += `<circle class="observer" cx="${f1(ox)}" cy="${f1(oy)}" r="3"/>`;
  // Moon: dark body, sunlit half always toward the Sun (left)
  g += `<circle class="moon-dark" cx="${f1(mx)}" cy="${f1(my)}" r="${MOON_R}"/>`;
  g += `<path class="moon-lit" d="M${f1(mx)},${f1(my - MOON_R)}A${MOON_R},${MOON_R} 0 0 0 ${f1(mx)},${f1(my + MOON_R)}Z"/>`;
  // Earth-facing half: dashed arc
  const phi = Math.atan2(uy, ux), rr = MOON_R + 4;
  const a = [mx + rr * Math.cos(phi - Math.PI / 2), my + rr * Math.sin(phi - Math.PI / 2)];
  const b = [mx + rr * Math.cos(phi + Math.PI / 2), my + rr * Math.sin(phi + Math.PI / 2)];
  g += `<path class="facing" d="M${f1(a[0])},${f1(a[1])}A${rr},${rr} 0 0 1 ${f1(b[0])},${f1(b[1])}"/>`;
  g += `<circle class="moon-hit" id="moon-handle" cx="${f1(mx)}" cy="${f1(my)}" r="22"/>`;
  return g;
}

// Moon as seen from Earth
const MARIA = [[-28, -38, 22, 16], [8, -44, 18, 13], [30, -12, 20, 18], [-8, 2, 26, 20], [-44, 6, 14, 22], [12, 38, 16, 11], [-30, 44, 12, 9]];
export function skyView(s) {
  const R = 104, cx = 150, cy = 146;
  const lit = polyPath(M.litPolygon(s.theta, R, s.hemi, 64), cx, cy);
  const rot = s.hemi === 'S' ? `rotate(180 ${cx} ${cy})` : '';
  const maria = MARIA.map(([x, y, rx, ry]) => `<ellipse cx="${cx + x}" cy="${cy + y}" rx="${rx}" ry="${ry}"/>`).join('');
  let g = `<rect class="sky" x="0" y="0" width="300" height="300" rx="14"/>`;
  for (const [x, y, r] of [[22, 28, 1.1], [270, 40, .9], [36, 250, .8], [262, 230, 1.2], [280, 120, .7], [18, 140, .8], [70, 18, .7], [236, 16, .8]])
    g += `<circle class="star" cx="${x}" cy="${y}" r="${r}"/>`;
  g += `<defs><clipPath id="lit-clip"><path d="${lit}"/></clipPath></defs>`;
  g += `<circle class="disk-dark" cx="${cx}" cy="${cy}" r="${R}"/>`;
  g += `<g class="maria-dim" transform="${rot}">${maria}</g>`;
  g += `<path class="disk-lit" d="${lit}"/>`;
  g += `<g clip-path="url(#lit-clip)"><g class="maria" transform="${rot}">${maria}</g></g>`;
  g += `<circle class="disk-rim" cx="${cx}" cy="${cy}" r="${R}"/>`;
  const t = M.norm(s.theta), fr = M.illuminatedFraction(t);
  let hint;
  if (fr < 0.02) hint = 'Sol quase atrás da Lua';
  else if (fr > 0.98) hint = 'Sol atrás do observador';
  else {
    const right = (Math.sin(t * Math.PI / 180) >= 0) === (s.hemi === 'N');
    hint = right ? 'Sol nesta direção →' : '← Sol nesta direção';
  }
  g += `<text class="sky-hint" x="150" y="26" text-anchor="middle">${hint}</text>`;
  g += `<text class="sky-lbl" x="150" y="284" text-anchor="middle">${s.hemi === 'N' ? 'visto do Hemisfério Norte' : 'visto do Hemisfério Sul'}</text>`;
  return g;
}

export function miniDisk(theta, hemi) {
  const R = 10;
  return `<svg viewBox="-12 -12 24 24" aria-hidden="true"><circle class="mini-dark" r="${R}"/>` +
    `<path class="mini-lit" d="${polyPath(M.litPolygon(theta, R, hemi, 20), 0, 0)}"/>` +
    `<circle class="mini-rim" r="${R}"/></svg>`;
}
